import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("parent sheet rates", () => {
  test("parent sheet rates", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-05"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "30.00", "to": "2026-03-04"})).toBe(true);
    const p_pam = ui.must(await ui.addPerson(pg_uma, {"name": "Pam", "grade": "A"}));
    await ui.loadSheet(pg_uma, `${sheet}-pp`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "40.00"})).toBe(true);
    const p_pip = ui.must(await ui.addPerson(pg_uma, {"name": "Pip", "grade": "C"}));
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    await ui.setSetting(pg_uma, "parent", `${sheet}-pp`);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.00", "date": "2026-03-01"}));
